import React, { useState } from 'react';
// CORREÇÃO: O caminho para o LoginScreen foi ajustado para ser mais preciso.
import LoginScreen from './components/auth/LoginScreen/LoginScreen';
// Futuramente, importaremos o AppLayout aqui

function App() {
  const [userRole, setUserRole] = useState(null);

  const loginAs = (role) => {
    setUserRole(role);
  };

  // Se não houver perfil, mostra o ecrã de login
  if (!userRole) {
    return <LoginScreen loginAs={loginAs} />;
  }

  // Se houver um perfil, mostra o painel correspondente
  // (Vamos construir isto a seguir)
  return (
    <div>
      <h1>Painel do {userRole}</h1>
      <button onClick={() => setUserRole(null)}>Logout</button>
    </div>
  );
}

export default App;
